addition نامی فنکشن پر غور کریں جو دو صحیح قدریں لیتا ہے، انھیں جمع کرتا ہے اور نتیجہ کال کرنے والے پروگرام کو واپس کرتا ہے۔ درج ذیل کوڈ کا حصہ یہ فنکشن بیان کرتا ہے:

// user-defined function (addition) program
#include <iostream.h>
#include <conio.h>
int addition (int a, int b)
{
int sum;
sum=a+b;
return (sum);
}
int main()
{
int z;
z = addition (55,33);
cout << "The sum of a and b is= " << z;
getch();
return 0;
}

پروگرام کا آؤٹ پٹ

The sum of a and b is =88

یوزر ڈیفائنڈ فنکشنز کا عمل

اوپر کے پروگرام میں addition (int a, int b) یوزر ڈیفائنڈ فنکشن کی مثال ہے جسے صارف نے دو صحیح قدروں (اس صورت میں 55 اور 33) کو جمع کرنے کے لیے بیان کیا ہے۔ یہ قدریں فنکشن کال addition (55,33) سے پاس کی جاتی ہیں۔ جمع کرنے کے بعد فنکشن درج ذیل بیان کے ذریعے حاصلِ جمع (88) کال کرنے والے پروگرام (اس صورت میں main) کو واپس کرتا ہے۔

return (sum);

حاصلِ جمع main() میں ویری ایبل z کو دیا جاتا ہے، جیسا کہ ذیل میں دکھایا گیا ہے:

z = addition (55, 33);

main میں کوڈ کی درج ذیل لائن نتیجہ اسکرین پر دکھانے کے لیے استعمال ہوتی ہے جیسا کہ اوپر کے پروگرام میں دکھایا گیا ہے۔

cout << "The sum of a and b is= " << z;

6.1.2 فنکشنز کے استعمال کے فوائد

فنکشنز کے ذریعے ہم اپنے پروگراموں کو زیادہ ماڈیولر انداز میں ترتیب دے سکتے ہیں۔ فنکشنز کا استعمال بہت سے فوائد فراہم کرتا ہے، جن میں شامل ہیں:

کوڈ کا دوبارہ استعمال: فنکشن کے اندر کا کوڈ پروگرام میں اسے بار بار کال کر کے دوبارہ استعمال کیا جا سکتا ہے۔

کوڈ کی تازہ کاری: فنکشن میں کوڈ تبدیل یا تازہ کرنا بہت آسان ہے، جو صرف ایک بار کرنا ہوتا ہے۔

پڑھنے اور سمجھنے میں آسانی: یہ کوڈ کو پڑھنے اور سمجھنے میں آسان بناتا ہے۔

